"""Escaped Markdown with no imported links, images, HTML or SVG execution."""
import html
import mistune
from markupsafe import Markup


class LocalRenderer(mistune.HTMLRenderer):
    def link(self, text, url, title=None):
        # Source navigation is generated by Flask, never by author-provided URLs.
        return text

    def image(self, text, url, title=None):
        return '<span class="ls-media-alt">' + html.escape(text) + '</span>'


def markdown(text):
    render = mistune.create_markdown(renderer=LocalRenderer(escape=True), plugins=['table'])
    return Markup(render(str(text)))
